@pytest.mark.smoke
def test_tc_01_07_navigation_is_hidden_behind_button_on_narrow_viewport(page, base_url, runtime_options) -> None:
    """Navigation is hidden behind button on narrow viewport

    ID: TC-01-07 | Priority: High | Source: studio:REQ-01

    Requirement REQ-01; boundary test (boundary)

    Preconditions:
      - Lab is open

    Expected:
      - The navigation is hidden
      - A button labeled 'Open navigation' with aria-expanded=false is shown

    Tags: boundary
    """
    test_data = {'viewport_width': 759}
    page_obj = ShellNavigationPage(page, runtime_options["resilience_policy"])
    # Step 1: Set viewport width to 759 px
    page_obj.set_viewport_width(test_data['viewport_width'])
    # Step 2: Navigate to /?release=v1
    page_obj.open(base_url, '/?release=v1')
    # Expected: The navigation is hidden
    assert not page_obj.is_navigation_visible()
    # Expected: A button labeled 'Open navigation' with aria-expanded=false is shown
    assert page_obj.is_nav_toggle_button_visible()


